// Songs made in create.html, kept in this browser (localStorage). window.UserSongs: list / save / remove.
// On tabs.html (generated by tab-viewer/build.py) it also adds them to the baked SONGS list once the page script ran.
// index.html's js/main.js reads UserSongs.list() itself.
(function () {
  const KEY = 'guitar3d-user-songs';
  const list = () => { try { const v = JSON.parse(localStorage.getItem(KEY) || '[]'); return Array.isArray(v) ? v : []; } catch { return []; } };
  const write = v => { try { localStorage.setItem(KEY, JSON.stringify(v)); return true; } catch (e) { console.warn('Could not save songs:', e); return false; } };
  window.UserSongs = {
    list,
    save(song) { return write(list().filter(s => s.id !== song.id).concat([song])); },
    remove(id) { return write(list().filter(s => s.id !== id)); },
  };

  function hookTabView() {
    // tabs.html declares `const SONGS`, `buildTabs` and `loadSong` in a classic script: global, so reachable here
    if (typeof SONGS === 'undefined' || typeof loadSong !== 'function') return;
    const mine = list().filter(s => s && s.score && s.score.notes && s.score.notes.length && !SONGS.some(x => x.id === s.id));
    if (!mine.length) return;
    for (const s of mine) SONGS.push({ ...s, title: s.title + ' ★', artist: s.artist || 'you', kind: s.kind || 'Auto tab', video: s.video || '', audio: 'data:,' });
    // a song without a YouTube video: hide the player and let the page fall back to the synth guitar
    if (typeof loadVideo === 'function' && typeof loadAudio === 'function') {
      const orig = loadVideo;
      window.loadVideo = s => { if (s.video) return orig(s); try { if (yt) yt.hide(); } catch {} ytOK = false; return loadAudio(); };
    }
    if (typeof buildTabs === 'function') buildTabs();
    const want = location.hash.slice(1);
    if (mine.some(s => s.id === want)) loadSong(want);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', hookTabView); else hookTabView();
})();
